begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select plan(6);
create temporary table rubric_identity_source(assessment_id uuid,rubric_id uuid);grant select,insert,update on rubric_identity_source to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99400000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Parent metadata source','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score)values('10000000-0000-4000-8000-000000000001','99410000-0000-4000-8000-000000000001','99400000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Native rubric identity','School authored',10);
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
insert into rubric_identity_source select'99410000-0000-4000-8000-000000000001',internal.create_rubric('99400000-0000-4000-8000-000000000001','Private rubric','school-id-1','[{"key":"explanation","title":"Explanation","levels":[{"key":"shown","label":"Shown","description":"Teacher definition"}]}]');select internal.configure_assessment_rubric((select assessment_id from rubric_identity_source),(select rubric_id from rubric_identity_source),1);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is(internal.read_assessment_rubric_identity('10000000-0000-4000-8000-000000000001',(select assessment_id from rubric_identity_source)),(select rubric_id from rubric_identity_source),'parent permitted assessment metadata retains pinned rubric identity');
select is((select count(*)from app.rubric_versions where id=(select rubric_id from rubric_identity_source)),0::bigint,'identity helper does not grant private rubric definition access');
select throws_ok($$select internal.read_assessment_rubric_identity('10000000-0000-4000-8000-000000000002','99410000-0000-4000-8000-000000000001')$$,'42501',null,'foreign metadata selector denied');
reset role;update app.parent_relationships set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and parent_actor_id='20000000-0000-4000-8000-000000000072';set local role cuevo_api;
select throws_ok($$select internal.read_assessment_rubric_identity('10000000-0000-4000-8000-000000000001','99410000-0000-4000-8000-000000000001')$$,'42501',null,'revoked guardian cannot retrieve rubric metadata');
reset role;select ok(not has_function_privilege('authenticated','internal.read_assessment_rubric_identity(uuid,uuid)','EXECUTE'),'browser has no raw metadata function grant');select ok(not has_function_privilege('cuevo_worker','internal.read_assessment_rubric_identity(uuid,uuid)','EXECUTE'),'worker has no rubric metadata function grant');select*from finish();rollback;
